export default function({$,$$,K,html,raw,put,S,opts,fmt,api}){async function booking(){$('#back').onclick=e=>{e.preventDefault();history.back()};const p=new URLSearchParams(location.search),id=+p.get('trip');let t;try{t=(await api('GET','schedules/'+id)).data}
catch(e){put($('#main'),html`<h1 class="u3">Trip not available</h1><p class="err" role="alert">${e.message}</p><p><a class="btn" href="index.html">Search again</a></p>`);return}
$('#tinfo').textContent=`${t.operator_name} · ${t.origin} → ${t.destination} · ${fmt.date(t.departure_at)} · ${fmt.time(t.departure_at)}`;const max=Math.min(10,t.seats_available);let n=Math.min(max,Math.max(1,+p.get('pax')||1));put($('#pax'),Array.from({length:max},(_,i)=>html`<option value="${i+1}"${i+1==n?' selected':''}>${i+1}</option>`));const names={};const draw=()=>{put($('#pf'),Array.from({length:n},(_,i)=>html`<fieldset class="card"><legend>Passenger ${i+1}</legend><label for="${'pn'+i}">Full name (as on ID)</label><input class="in pn" id="${'pn'+i}" data-i="${i}" maxlength="60" value="${names[i]||''}" required></fieldset>`));$$('.pn').forEach(e=>e.oninput=()=>{names[e.dataset.i]=e.value});$('#ssum').textContent=`${n} passenger${n>1?'s':''} · ${t.seats_available} seat${t.seats_available==1?'':'s'} left on this trip`;$('#fare').textContent=K(n*t.fare_per_seat);$('#total').textContent=K(n*t.fare_per_seat);};$('#pax').onchange=()=>{n=+$('#pax').value;draw()};$('#go').onclick=async()=>{const list=Array.from({length:n},(_,i)=>(names[i]||'').trim());if(list.some(x=>!x)){$('#msg').textContent='Enter every passenger name.';return}
$('#go').disabled=true;$('#msg').textContent='Reserving your seats…';try{const r=await api('POST','bookings',{schedule_id:t.schedule_id,seats:n,passenger_name:list.join(', ')});location=`checkout.html?id=${r.data.booking.booking_id}`;}catch(e){$('#go').disabled=false;const fe=Object.values(e.fieldErrors||{})[0];$('#msg').textContent=fe||e.message;}
};draw();}
return booking;}